const body = $json.body || $json || {};
const docType = body.doc_type || 'GENERAL';
const docDate = new Date().toISOString().split('T')[0].replace(/-/g, '');
const seq = Math.floor(Math.random() * 9000) + 1000;
const fallbackCode = `${docType.substring(0, 3).toUpperCase()}-${docDate}-${seq}`;
const docCode = String(body.so_van_ban || body.doc_code || fallbackCode).trim();
const senderName = String(body.noi_gui || body.sender_name || body.source || 'Ngoại bộ').trim();
const title = String(body.trich_yeu || body.title || 'Văn bản đến').trim();
const assignee = String(body.assignee_id || body.assigned_to || '').trim();
const receivedAt = String(body.ngay_nhan || new Date().toISOString().slice(0, 10)).slice(0, 10);
return [{json: {...body, id: body.id || '', doc_code: docCode, so_van_ban: docCode, sender_name: senderName, noi_gui: senderName, title, trich_yeu: title, assigned_to: assignee, received_at: receivedAt}}];

